INSERT INTO `v1_044979866161470e9151e70f08406dc9c000d761247e57284995adec2e2e4e76` VALUES (-363, 140301, "あんたにとって\nプリンセスって誰なの？", 1, 0, "ティア", 0, 2, 2, 1, 73, 0);
INSERT INTO `v1_044979866161470e9151e70f08406dc9c000d761247e57284995adec2e2e4e76` VALUES (-363, 140301, "ちょっ……なによ\nセクハラすんじゃないわよ\nほら、早く選びなさいよ", 2, 0, "ティア", 1.384, 3, 5, 2, 73, 1);
INSERT INTO `v1_044979866161470e9151e70f08406dc9c000d761247e57284995adec2e2e4e76` VALUES (-363, 140301, "……～っ……\nや、やめなさいっての\nくすぐったいんだから……", 3, 0, "ティア", 0, 5, 5, 3, 73, 1);
INSERT INTO `v1_044979866161470e9151e70f08406dc9c000d761247e57284995adec2e2e4e76` VALUES (-363, 140301, "……あんた。\nあたしをからかってるの？\nそ、それとも……", 4, 0, "ティア", 6.175, 5, 3, 4, 73, 1);
INSERT INTO `v1_044979866161470e9151e70f08406dc9c000d761247e57284995adec2e2e4e76` VALUES (-363, 140301, "あたしを選ぼう、とか……\n言わないわよね……？", 5, 0, "ティア", 0, 4, 4, 5, 73, 1);
